18	func (r *fakeCommandRunner) fakeGraphStoreCommand(dir, name string, args []string) (fakeCommandResponse, bool) {
19		if name != "entire" || len(args) < 2 || args[0] != "graph" || (args[1] != "index" && args[1] != "store") {
20			return fakeCommandResponse{}, false
21		}
22		profile := "full"
23		for i := 2; i+1 < len(args); i++ {
24			if args[i] == "--profile" {
25				profile = args[i+1]
26			}
27		}
28		key := dir + "\x00" + profile
29		if args[1] == "store" {
30			if d, ok := r.graphStoreFixtures[key]; ok {
31				raw, _ := json.Marshal(d)
32				return fakeCommandResponse{stdout: string(raw)}, true
33			}
34			return fakeCommandResponse{stdout: `{"contract_version":1,"store_unavailable":true}`}, true
35		}
36		snapshot, ok := r.responses[fakeCommandKey("entire", "graph", "snapshot", "--repo", dir, "--format", "ndjson", "--no-network")]
37		if !ok {
38			return fakeCommandResponse{}, false
39		}
40		force := false
41		for _, arg := range args {
42			if arg == "--force" {
43				force = true
44			}
45		}
46		if d, ok := r.graphStoreFixtures[key]; ok && !force {
47			if db, err := openSemanticReadDB(graphStoreSource(d, "").StorePath); err == nil {
48				db.Close()
49				return fakeCommandResponse{stdout: `{"index_cache_hit":true}`}, true
50			}
51		}
52		if snapshot.err != nil {
53			return snapshot, true
54		}
55		ignore, err := loadBrainIgnore(dir)
56		if err != nil {
57			return fakeCommandResponse{err: err}, true
58		}
59		header, counts, filtered, err := filterSemanticSnapshot([]byte(snapshot.stdout), ignore, dir)
60		if err != nil {
61			return fakeCommandResponse{err: err}, true
62		}
63		providerDir, err := os.MkdirTemp(dir, ".graph-fixture-")
64		if err != nil {
65			return fakeCommandResponse{err: err}, true
66		}
67		generation, _, err := buildSemanticGeneration(context.Background(), providerDir, dir, "fixture", bytes.NewReader(filtered), "fixture", header, counts, time.Now())
68		if err != nil {
69			return fakeCommandResponse{err: err}, true
70		}
71		path := filepath.Join(providerDir, generation, semanticSQLiteName)
