84		_, err = db.Exec("INSERT INTO meta(key,value) VALUES('entry_digest',?)", string(raw))
85		db.Close()
86		if err != nil {
87			return fakeCommandResponse{err: err}, true
88		}
89		if r.graphStoreFixtures == nil {
